mapper.select:
SELECT COUNT(*) FROM product p JOIN ( SELECT category_id, LTRIM(SYS_CONNECT_BY_PATH(category_name, '>'), '>') AS category_path FROM category START WITH parent_id IS NULL CONNECT BY PRIOR category_id = parent_id ) c ON p.category_id = c.category_id
AND (p.product_name LIKE '%' || #{keyword} || '%' OR c.category_path LIKE '%' || #{keyword} || '%')
AND p.status = #{status}

mapper.update:
UPDATE STOCK
SET quantity = #{quantity}
WHERE product_id = #{productId}
